mod cloud;
mod get;
mod set;

use async_trait::async_trait;

use cloud::CloudCommandGroup;
use get::GetConfig;
use set::SetConfig;

use crate::{
    cmd_uri::CmdUri,
    component::{AzCommand, AzComponentImpl, AzCommandGroup, AzComponentCtx},
    error::{AzError, AzInternalError},
    pb::{
        cmd_interface, execute_response, CmdComponent, CmdHelp, CmdInterface, CmdOutputFormat,
        CmdParams,
    },
    VERSION,
};

#[derive(Debug, Default)]
pub struct ConfigComponent {}

// should be generated by component macro later
#[async_trait]
impl AzCommandGroup for ConfigComponent {
    const URI: &'static str = "cmd://azure/config/";
    fn build_interface(depth: Option<u32>) -> CmdInterface {
        let mut groups = vec![];
        let mut commands = vec![];
        if depth.is_none_or(|d| d > 0) {
            let depth = depth.map(|d| d - 1);
            groups.push(CloudCommandGroup::build_interface(depth).as_command_group().unwrap().to_owned());
            commands.push(GetConfig::build_interface(depth).as_command().unwrap().to_owned());
            commands.push(SetConfig::build_interface(depth).as_command().unwrap().to_owned());
        }
        CmdInterface {
            level: Some(cmd_interface::Level::Component(CmdComponent {
                name: "config".to_string(),
                help: Some(CmdHelp {
                    short: "Manage Azure configuration".to_string(),
                    long: None,
                }),
                uri: Self::uri().to_string(),
                version: VERSION.to_string(),
                groups,
                commands,
            })),
        }
    }

    fn find_interface(
        depth: Option<u32>,
        mut segments: impl Iterator<Item = String>,
    ) -> Option<CmdInterface> {
        match segments.next().as_deref() {
            None => Some(Self::build_interface(depth)),
            Some("get") => Some(GetConfig::build_interface(depth)),
            Some("set") => Some(SetConfig::build_interface(depth)),
            Some("cloud") => CloudCommandGroup::find_interface(depth, segments),
            _ => None, // not found
        }
    }

    fn resolve_cmd_uri(mut segments: impl Iterator<Item = String>) -> Option<CmdUri> {
        match segments.next().as_deref() {
            None => Some(Self::uri()),
            Some("get") => {
                Some(GetConfig::uri().with_param_values("key", segments.collect::<Vec<_>>()))
            }
            Some("set") => {
                Some(SetConfig::uri().with_param_values("value", segments.collect::<Vec<_>>()))
            }
            Some("cloud") => CloudCommandGroup::resolve_cmd_uri(segments),
            _ => None,
        }
    }

    async fn execute_group<T: AzComponentCtx>(
        ctx: &T,
        mut segments: impl Iterator<Item = String> + Send,
        params: Option<CmdParams>,
        output_format: Option<CmdOutputFormat>,
    ) -> Result<execute_response::Data, AzError> {
        match segments.next().as_deref() {
            Some("get") => GetConfig::execute(ctx, params, output_format).await,
            Some("set") => SetConfig::execute(ctx, params, output_format).await,
            Some("cloud") => {
                CloudCommandGroup::execute_group(ctx, segments, params, output_format).await
            }
            Some(other) => Err(AzInternalError::InvalidCmdUriError(other.to_string()).into()),
            None => Err(AzInternalError::InvalidCmdUriError(Self::uri().to_string()).into()),
        }
    }
}

impl<T: AzComponentCtx> AzComponentImpl<T> for ConfigComponent {}
